refentry.refsect1:
&reftitle.description;

 stringtrim
 stringstring
 stringcharacters" \f\n\r\t\v\x00"

यो function ले string को सुरु र end from whitespace हटाइएको एउटा string return गर्दछ। दोस्रो parameter बिना, trim ले यी characters हटाउनेछ:
&strings.stripped.characters;

&reftitle.changelog;





    &Version;
    &Description;





    8.6.0
    Form feed character ("\f") लाई characters को default value मा थपिएको थियो।

  &reftitle.examples;



    trim को प्रयोगको उदाहरण


<?php

$text   = "\t\tThese are a few words :) ...  ";
$binary = "\x09Example string\x0A";
$hello  = "Hello World";
var_dump($text, $binary, $hello);

print "\n";

$trimmed = trim($text);
var_dump($trimmed);

$trimmed = trim($text, " \t.");
var_dump($trimmed);

$trimmed = trim($hello, "Hdle");
var_dump($trimmed);

$trimmed = trim($hello, 'HdWr');
var_dump($trimmed);

// trim the ASCII control characters at the beginning and end of $binary
// (from 0 to 31 inclusive)
$clean = trim($binary, "\x00..\x1F");
var_dump($clean);

?>


    &example.outputs;


string(32) "		These are a few words :) ...  "
string(16) "	Example string
"
string(11) "Hello World"

string(28) "These are a few words :) ..."
string(24) "These are a few words :)"
string(5) "o Wor"
string(9) "ello Worl"
string(14) "Example string"







    trim प्रयोग गरी array values trim गर्ने


<?php
function trim_value(&$value) 
{ 
    $value = trim($value); 
}

$fruit = array('apple','banana ', ' cranberry ');
var_dump($fruit);

array_walk($fruit, 'trim_value');
var_dump($fruit);

?>


    &example.outputs;


array(3) {
  [0]=>
  string(5) "apple"
  [1]=>
  string(7) "banana "
  [2]=>
  string(11) " cranberry "
}
array(3) {
  [0]=>
  string(5) "apple"
  [1]=>
  string(6) "banana"
  [2]=>
  string(9) "cranberry"
}

  &reftitle.notes;

   सम्भावित समस्या (gotcha): बीचका characters हटाउने

किनभने trim ले एउटा string को सुरु र end from characters trim गर्दछ, त्यसैले बीच from characters हट्दा (वा नहट्दा) अलमल हुन सक्छ। trim('abc', 'bad') ले 'a' र 'b' दुवै हटाउँछ किनभने यसले 'a' लाई trim गर्दछ, जसले गर्दा 'b' सुरुमा सरेर त्यो पनि trim हुन पुग्छ। त्यसैले, यही कारणले यो "काम गर्छ" जबकि trim('abc', 'b') ले काम नगरेको जस्तो देखिन्छ।
